-- YG-1311 iş sonucu doğrulama, karantina, manuel uzlaştırma; YG-1312 dönem uzlaştırması ve sahipli fark.
CREATE TABLE entegrasyon_kaydi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), entegrasyon_ref uuid NOT NULL REFERENCES entegrasyon_tanimi (kimlik), dis_kimlik text NOT NULL, donem text, kritik_deger numeric(16,2), karsi_durum text, beklenen_sonuc text NOT NULL, sonuc_ref text, durum text NOT NULL CHECK (durum IN ('Doğrulandı', 'Karantina', 'Uzlaştırıldı')), hata text, uzlastirma_karari text, uzlastirma_gerekcesi text, uzlastiran_ref text REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now(), UNIQUE (entegrasyon_ref, dis_kimlik));
CREATE TABLE entegrasyon_uzlastirma (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), entegrasyon_ref uuid NOT NULL REFERENCES entegrasyon_tanimi (kimlik), donem text NOT NULL, sistem_sayisi integer NOT NULL, karsi_sayisi integer NOT NULL, sistem_toplami numeric(16,2) NOT NULL, karsi_toplami numeric(16,2) NOT NULL, fark_sayisi integer NOT NULL, yapan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now());
CREATE TABLE entegrasyon_farki (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), uzlastirma_ref uuid NOT NULL REFERENCES entegrasyon_uzlastirma (kimlik), tur text NOT NULL CHECK (tur IN ('Kayıt Sayısı', 'Kimlik', 'Kritik Değer', 'Durum', 'Dönem Toplamı')), dis_kimlik text, aciklama text NOT NULL, karar text, karar_veren_ref text REFERENCES kullanici_hesabi (kimlik));
GRANT SELECT, INSERT, UPDATE ON entegrasyon_kaydi, entegrasyon_uzlastirma, entegrasyon_farki TO yatonet_uygulama;
